  static final RegExp _ph = RegExp(r'\$\{[^}]*\}|\$[A-Za-z_]\w*');
  static List<(RegExp, List<String>)>? _compiled;

  static List<(RegExp, List<String>)> _compile() {
    final out = <(RegExp, List<String>)>[];
    for (final row in _templates) {
      final en = row[0];
      final tokens = <String>[];
      final buf = StringBuffer('^');
      int last = 0;
      for (final m in _ph.allMatches(en)) {
        buf.write(RegExp.escape(en.substring(last, m.start)));
        buf.write('(.*?)');
        tokens.add(m.group(0)!);
        last = m.end;
      }
      buf.write(RegExp.escape(en.substring(last)));
      buf.write(r'$');
      out.add((RegExp(buf.toString(), dotAll: true), tokens));
    }
    return out;
  }

  /// [lang] (fr/ru/es) 문구. 없으면 null (영어를 씀)
  static String? tr(String lang, String en) {
    final int li = langs.indexOf(lang);
    if (li < 0) return null;
    final hit = _exact[en];
    if (hit != null) return hit[li];
    final compiled = _compiled ??= _compile();
    for (int i = 0; i < compiled.length; i++) {
      final (re, tokens) = compiled[i];
      final m = re.firstMatch(en);
      if (m == null) continue;
      String out = _templates[i][li + 1];
      for (int k = 0; k < tokens.length; k++) {
        out = out.replaceAll(tokens[k], m.group(k + 1) ?? '');
      }
      return out;
    }
    return null;
  }
